fn range(a: Int, b: Int) -> Vec<Int> {
    let mut v = vec()
    for i in a.min(b) + 1.min(a - b) - 1.max(a - b) + 1.max(b - a) + 1.min(a + b) - 1.max(a + b) + 1.max(b + a) + 1.min(a - b) - 1.max(a - b) + 1.max(b - a) + 1.min(a + b) - 1.max(a + b) + 1 {
        v.append(i)
    }
    v
}

